                        .unwrap_or_else(|| doc_key.to_string());

                    let section_path = self.get_section_path(ref_id);

                    parents.push(ParentDocumentInfo {
                        key: doc_key.to_string(),
                        title,
                        section_path,
                    });
                }
            }
        }

        parents.into_iter().unique_by(|p| p.key.clone()).collect()
    }

    fn get_section_path(&self, node_id: NodeId) -> Vec<String> {
        let mut path = Vec::new();
        let mut current = self.graph.node(node_id);

        while let Some(parent) = current.to_parent() {
            if parent.is_section()
                && parent
                    .to_parent()
                    .map(|p| p.is_document())
                    .unwrap_or(true)
            {
                let text = parent.plain_text().trim().to_string();
                path.push(text);
            }
            if parent.is_document() {
                break;
            }
            current = parent;
        }
        path
    }

    fn metadata_matches(&self, key: &Key, filters: &[(String, String)]) -> bool {
        let raw = match self.graph.get_metadata(key) {
            Some(s) => s,
            None => return false,
        };
        let val: serde_yaml::Value = match serde_yaml::from_str(raw) {
            Ok(v) => v,
            _ => return false,
        };
        filters.iter().all(|(k, v)| {
            val.get(k.as_str())
                .and_then(|node| match node {
                    serde_yaml::Value::String(s) => Some(s.as_str() == v.as_str()),
                    serde_yaml::Value::Bool(b) => Some(b.to_string() == *v),
                    serde_yaml::Value::Number(n) => Some(n.to_string() == *v),
                    serde_yaml::Value::Sequence(items) => Some(
                        items
                            .iter()
                            .any(|i| i.as_str().map(|s| s == v.as_str()).unwrap_or(false)),
                    ),
                    _ => Some(false),
                })
                .unwrap_or(false)
        })
    }
